import {mountExperiment} from './experiment-ui.js';
import {R,C,T,B,fmt,stats,note,node,flow,table,bars} from './computer-ui.js';
import * as M from './security-models.js';
const labs={};
const gates=checks=>`<div class="sec-gates">${checks.map(([label,pass])=>`<div class="${pass?'pass':'fail'}"><span aria-hidden="true">${pass?'✓':'×'}</span><strong>${label}</strong><small>${pass?'passes':'fails'}</small></div>`).join('')}</div>`;
const tiles=items=>`<div class="sec-tiles">${items.map(([label,value,ok])=>`<div class="${ok?'pass':'fail'}"><small>${label}</small><strong>${value}</strong></div>`).join('')}</div>`;
const code=value=>`<pre class="sec-code"><code>${M.escapeHTML(value)}</code></pre>`;
const verdict=(allowed,yes='Allowed',no='Denied')=>`<div class="sec-verdict ${allowed?'pass':'fail'}">${allowed?yes:no}</div>`;

labs.assets=()=>({title:'Match a loss to its defense',state:{threat:'Read private invoices',control:'Tenant authorization'},controls:[C('threat','Unacceptable outcome',['Read private invoices','Alter a refund amount','Exhaust every worker']),C('control','Primary control',['Tenant authorization','Atomic refund invariant','Bounded work admission'])],render:s=>{
 const cases={'Read private invoices':['Confidentiality','Invoice contents','Tenant authorization'],'Alter a refund amount':['Integrity','Paid amount ≥ total refunds','Atomic refund invariant'],'Exhaust every worker':['Availability','Capacity for legitimate callers','Bounded work admission']},[property,asset,control]=cases[s.threat],matched=s.control===control;
 return flow([['Asset / invariant',asset],['Loss',s.threat,'purple'],['Property',property,'blue']])+tiles([[s.control,matched?'Addresses this path':'Different failure path',matched]])+note(matched?'Now test this invariant at every entry point to the asset.':'A useful control can still be the wrong control for this particular loss.',!matched);
},foot:'Three fixed scenarios, one primary control each. Real defenses overlap; matching is not a risk score or proof of complete coverage.'});

labs.boundaries=()=>({title:'Trace the source of authority',state:{source:'Browser header',validated:false},controls:[C('source','Source of role=admin',['Browser header','Queue message','Verified server session']),T('validated','Server independently verifies the admin grant')],render:s=>{
 const trusted=M.trustDecision(s.source,s.validated);
 return `<div class="sec-boundary"><div><small>Claim arrives</small>${node(s.source,'role = admin','purple')}</div><div class="sec-checkpoint"><span>TRUST BOUNDARY</span><b>${trusted?'Evidence established':'Claim only'}</b></div><div><small>Enforcement point</small>${node('Server policy',trusted?'May use admin grant':'Reject unverified grant',trusted?'green':'blue')}</div></div>`+verdict(trusted,'Authority established','No authority established')+note('Verified here means the server has authenticated the subject and confirmed this grant from an authoritative policy source.');
},foot:'One admin claim, assumed current and in scope. Transport security, input validation, and authorization of the specific action remain separate checks.'});

labs.privilege=()=>({title:'Inspect the compromised worker’s reach',state:{role:'Shared administrator'},controls:[C('role','Runtime identity',Object.keys(M.permissionSets))],render:s=>{
 const permitted=M.permissionSets[s.role];
 return `<div class="sec-capabilities"><div class="sec-principal">Order worker<br><strong>${s.role}</strong><small>Assume this process is compromised</small></div><div>${M.permissionSets['Shared administrator'].map(p=>`<div class="sec-capability ${permitted.includes(p)?'reachable':''}"><span>${permitted.includes(p)?'→':'×'}</span>${p}<small>${permitted.includes(p)?'reachable':'denied'}</small></div>`).join('')}</div></div>`+stats(['Granted operations',permitted.length],['Order updates work',permitted.includes('Update orders')?'Yes':'No'])+note('The narrowest useful identity here is Order worker: it preserves the required update while removing unrelated authority.');
},foot:'Fixed action-level role map in one environment. Resource scope, identity theft prevention, and temporary elevation are not simulated.'});

labs['attack-paths']=()=>({title:'Close independent paths to the data',state:{objectCheck:false,privateStorage:false,scopedBuild:false},controls:[T('objectCheck','Enforce object authorization'),T('privateStorage','Keep exported storage private'),T('scopedBuild','Remove production export from build identity')],render:s=>{
 const paths=M.attackPaths(s);return `<div class="sec-routes">${paths.map(p=>`<div class="${p.blocked?'closed':'open'}"><span>${p.name}</span><b>${p.blocked?'× blocked':'→ data reachable'}</b><small>${p.control}</small></div>`).join('')}</div>`+stats(['Open modeled routes',paths.filter(p=>!p.blocked).length],['Independent paths',3])+note('Toggle one control. Only its own route changes; the other routes still need their own enforcement.');
},foot:'Three independent example routes, not an exhaustive attack graph. A blocked modeled route says nothing about unmodeled entry points.'});

labs.passwords=()=>({title:'Separate per-account work',state:{ms:100,accounts:10,uniqueSalt:true,lanes:1},controls:[R('ms','Cost per candidate per lane (ms)',10,500,10),R('accounts','Accounts with the same weak password',1,100),T('uniqueSalt','Distinct salt for every account'),R('lanes','Parallel compute lanes',1,32)],render:s=>{
 const r=M.passwordCost(s.ms,s.accounts,s.uniqueSalt,s.lanes);
 return `<div class="sec-salts">${Array.from({length:Math.min(s.accounts,12)},(_,i)=>`<div><span>User ${i+1}</span><b>${s.uniqueSalt?'salt '+(i+1):'same salt'}</b><small>${s.uniqueSalt?'separate work':'reusable work'}</small></div>`).join('')}</div>`+stats(['Total candidate evaluations',fmt(r.work,0)],['Ideal elapsed time',`${fmt(r.seconds/3600,1)} h`],['Candidates / second',fmt(r.perSecond)])+note('The same million-candidate search is needed for each unique salt. Raising KDF cost slows every lane; more hardware adds parallelism.');
},foot:'Fixed search of one million candidates containing the shared weak password, all candidates evaluated; ideal lanes and no overhead. This is arithmetic, not a cracking benchmark. Real KDF memory requirements also matter.'});

labs.passkeys=()=>({title:'Compare a relayed code with an origin-bound proof',state:{kind:'Password + OTP',lookalike:true,fresh:true},controls:[C('kind','Authentication proof',['Password + OTP','Origin-bound passkey']),T('lookalike','Login starts at a lookalike origin'),T('fresh','Proof answers the current fresh challenge / code')],render:s=>{
 const r=M.factorResult(s.kind,s.lookalike,s.fresh);return flow([['Browser origin',s.lookalike?'lookalike.example':'service.example','purple'],['Proof',s.kind],['Real verifier',r.accepted?'Accepts proof':'Rejects proof','blue']])+verdict(r.accepted)+note(r.reason,s.lookalike&&r.accepted);
},foot:'A lookalike has a different registrable domain. OTP case assumes successful real-time relay; passkey case assumes correct origin/RP verification. Other verifier checks, recovery, and session theft are outside this model.'});

labs.sessions=()=>({title:'Promote, expire, and revoke a session',state:{rotate:true,loggedIn:false,currentId:'S0',revoked:false,now:0,expires:60},controls:[T('rotate','Rotate identifier on authentication'),B('login','Authenticate user'),R('now','Minutes after authentication',0,90),B('revoke','Revoke session')],onChange:(s,k)=>{if(k==='rotate'){s.loggedIn=false;s.currentId='S0';s.revoked=false;s.now=0;}},actions:{login:s=>{if(!s.loggedIn){s.loggedIn=true;s.currentId=s.rotate?'S1':'S0';s.revoked=false;}},revoke:s=>{s.revoked=true;}},render:s=>flow([['Known before login','S0','purple'],['Current browser ID',s.currentId],['Server session',!s.loggedIn?'Anonymous':s.revoked?'Revoked':s.now>=60?'Expired':'Authenticated','blue']])+tiles([['Current browser request',M.sessionAccept(s,s.currentId)?'Accepted':'Rejected',M.sessionAccept(s,s.currentId)],['Copied pre-login S0',M.sessionAccept(s,'S0')?'Accepted':'Rejected',!M.sessionAccept(s,'S0')]])+note('Authenticate with rotation disabled to see fixation. Then reset and rotate; the old identifier no longer names the authenticated session.'),foot:'One server-side session, absolute 60-minute lifetime, fixed illustrative IDs (real IDs must be unpredictable). Revoke acts on server validity; reset starts a new scenario.'});

labs.federation=()=>({title:'Follow the authorization-code handoff',state:{redirect:true,correlated:true,stolen:true,pkce:true},controls:[T('redirect','Callback URI exactly registered'),T('correlated','Callback bound to initiating browser transaction'),T('stolen','Interceptor attempts redemption without verifier'),T('pkce','Enforce PKCE at the token endpoint')],render:s=>{
 const checks=M.oauthChecks(s),ok=checks.every(x=>x[1]);return flow([['Browser','Start login'],['Authorization server','Issue one-use code','purple'],['Token endpoint',s.stolen?'Interceptor redeems':'Original client redeems','blue']])+gates(checks)+verdict(ok,'Modeled flow accepted','Modeled flow rejected')+note(s.stolen&&ok?'Without the verifier binding, this intercepted code is redeemable.':'A valid callback and a redeemable code are separate requirements.',s.stolen&&ok);
},foot:'Abstract authorization-code scenario; the interceptor lacks the PKCE verifier. No protocol messages or tokens are generated. Token validation, client authentication where required, and OIDC nonce checks remain necessary.'});

labs.objects=()=>({title:'Change the resource without changing the user',state:{authenticated:true,owner:false,action:'Read',role:'Viewer'},controls:[T('authenticated','Caller is authenticated'),T('owner','Caller owns this document'),C('role','Role in this scope',['Viewer','Editor','Admin']),C('action','Requested action',['Read','Edit'])],render:s=>{
 const allowed=M.objectAccess(s);return flow([['Subject',s.authenticated?s.role:'Anonymous'],['Resource',s.owner?'Own document':'Another user’s document','purple'],['Operation',s.action,'blue']])+verdict(allowed)+table(['Role','Own: read','Own: edit','Other: read / edit'],['Viewer','Editor','Admin'].map(role=>[role,...[true,true,false].map((owner,i)=>M.objectAccess({authenticated:true,owner,action:i===1?'Edit':'Read',role})?'allow':'deny')]))+note('The table assumes authentication. Admin explicitly has broad access inside this toy scope; that exception must itself be a deliberate policy.');
},foot:'One resource scope, no cross-tenant admin grant. The decision is recomputed from subject, action, and actual resource on every change.'});

labs.tenants=()=>({title:'Follow tenant A through cache and storage',state:{cacheHit:true,cacheScoped:false,queryScoped:true,enforceTenant:false},controls:[T('cacheHit','Serve from cache'),T('cacheScoped','Cache key includes verified tenant'),T('queryScoped','Database query includes verified tenant'),T('enforceTenant','Check returned object belongs to caller’s tenant')],render:s=>{
 const r=M.tenantRead(s);return flow([['Authenticated context','Tenant A · object 7'],[s.cacheHit?'Cache hit':'Database read',s.cacheHit?s.cacheScoped?'A:7':'7':s.queryScoped?'tenant=A AND id=7':'id=7','purple'],['Returned record',`Tenant ${r.returnedTenant} · object 7`,'blue']])+verdict(!r.leak,r.allowed?'Own-tenant record delivered':'Mismatched record rejected','CROSS-TENANT DISCLOSURE')+note('On a cache hit, changing the SQL query cannot change the record served. Put scope on every serving path.',r.leak);
},foot:'Unscoped lookup deterministically finds B’s record; scoped lookup finds A’s. The final object check fails closed, but does not repair a broken cache key or query.'});

labs.policies=()=>({title:'Compose a policy from visible conditions',state:{role:'Editor',action:'Edit',owns:true,locked:false},controls:[C('role','Role',['Viewer','Editor','Admin','Unknown']),C('action','Action',['Read','Edit','Delete','New action']),T('owns','Caller owns the resource'),T('locked','Record is locked against writes')],render:s=>{
 const r=M.policyDecision(s.role,s.action,s.owns,s.locked);return gates([['Role explicitly grants this action',r.roleAllows],['Owner or explicit admin exception',r.relationAllows],['No restriction blocks this operation',!r.restriction]])+`<div class="sec-expression">role grant <b>AND</b> relation <b>AND</b> no restriction</div>`+verdict(r.allowed)+note('Try Admin + Edit + locked. A broad role still meets an explicit restriction. Unknown actions receive no grant.');
},foot:'A complete toy rule for these roles and actions; policies in a real system may use different exceptions. No concurrent policy changes are modeled.'});

labs.tokens=()=>({title:'Walk the token acceptance gates',state:{profile:'Valid token',now:10},controls:[C('profile','Token fixture',['Valid token','Bad signature','Unapproved algorithm','Wrong issuer','Wrong audience']),R('now','Current minute (expires at 60)',0,90)],render:s=>{
 const checks=M.tokenChecks(s.profile,s.now);return `<div class="sec-token"><span>header<br><b>alg · kid</b></span><span>payload<br><b>iss · aud · sub · exp</b></span><span>signature<br><b>authenticates bytes</b></span></div>`+gates(checks)+verdict(checks.every(x=>x[1]),'Identity evidence accepted','Token rejected')+note('Even an accepted token still needs action/resource authorization. Decoding the middle segment does not pass any of these gates.');
},foot:'Named verification-result fixtures, not JWT parsing or cryptography. Production validation must use a maintained library and a specific trust policy.'});

labs.injection=()=>({title:'Keep a value out of SQL structure',state:{bound:false,malicious:true},controls:[T('bound','Bind input as a parameter'),T('malicious','Input contains SQL syntax')],render:s=>{
 const input=s.malicious?"' OR '1'='1":'alice',r=M.injectionOutcome(s.bound,s.malicious);return `<div class="sec-compare"><div><h3>Input value</h3>${code(input)}</div><div><h3>Query sent</h3>${code(s.bound?'SELECT name FROM users\nWHERE name = $1':`SELECT name FROM users\nWHERE name = '${input}'`)}</div></div>`+(s.bound?code('Separate parameter $1 = '+JSON.stringify(input)):'')+tiles([['Parser boundary',r.structureChanged?'Input changes the predicate':'Input remains a value',!r.structureChanged],['Modeled matches',`${r.rows} of 3 records`,!r.structureChanged]])+note('With binding enabled, SQL-looking characters search for that literal name. There is no matching user in this fixture.',r.structureChanged);
},foot:'Fixed three-user example and a modeled result; no SQL executes. Parameters bind values, not arbitrary identifiers or SQL keywords.'});

labs.xss=()=>({title:'Choose what the browser is asked to parse',state:{sink:'HTML parser',policy:false},controls:[C('sink','Output sink',['HTML parser','Text sink']),T('policy','Strict CSP blocks inline event handlers')],render:s=>{
 const parsed=s.sink==='HTML parser',execution=parsed&&!s.policy;return code('<img src="invalid" onerror="DEMO_ACTION()">')+flow([['Untrusted string','User-supplied markup','purple'],['Sink',s.sink],['Interpretation',parsed?'Element + handler':'Literal text','blue']])+tiles([['DOM structure',parsed?'Input becomes markup':'No input-created elements',!parsed],['Illustrative handler',execution?'Could execute':'Does not execute',!execution]])+note('This page always renders the example as escaped text. The diagram models interpretation; the handler never runs. CSP can block this handler while injected markup remains.',execution);
},foot:'One inline-handler example, no real payload execution. A text sink is for literal text; trusted rich HTML requires context-aware sanitization. This is not a complete CSP model.'});

labs.csrf=()=>({title:'Separate the request from its response',state:{sameSite:'None',originCheck:false,tokenCheck:false,cors:false},controls:[C('sameSite','Explicit session-cookie SameSite',['None','Lax','Strict']),T('originCheck','Server rejects the foreign Origin'),T('tokenCheck','Server requires the missing anti-CSRF token'),T('cors','Allow this foreign origin to read credentialed responses')],render:s=>{
 const r=M.csrfModel(s);return `<div class="sec-browser-lanes"><div><small>OUTBOUND · browser → server</small>${flow([['Simple POST','Sent'],['Session cookie',r.cookie?'Attached':'Withheld','purple'],['Authenticated write',r.changed?'Happens':'Rejected','blue']])}</div><div><small>INBOUND · server → calling JavaScript</small>${flow([['Response','Server already processed request'],['CORS read gate',r.responseReadable?'Readable':'Hidden from caller','purple']])}</div></div>`+note(r.changed?'The write occurs even when CORS hides the response. Enable an appropriate server check or withhold the session cookie.':'This modeled authenticated write is blocked. CORS response access is a separate decision.',r.changed);
},foot:'Cross-site credentialed fetch POST with safelisted content type, HTTPS, third-party cookies permitted, explicit SameSite values. None also uses Secure. No preflight; no other credential source or authentication route.'});

labs.ssrf=()=>({title:'Validate the destination actually reached',state:{destination:'Allowed host redirects inward',validateEachHop:false,egress:false},controls:[C('destination','Fetch route',['Allowed public host','Allowed host redirects inward','Direct internal address']),T('validateEachHop','Revalidate redirect destinations'),T('egress','Network policy denies internal destinations')],render:s=>{
 const r=M.ssrfModel(s.destination,s.validateEachHop,s.egress);return flow([['Server fetcher','Initial allowlist enforced'],['Route',s.destination,'purple'],['Application check',r.appBlocked?'Blocked':'Permitted','blue'],['Internal service',r.internalReached?'Reached':'Not reached']])+verdict(!r.internalReached,'No internal reach on this route','INTERNAL SERVICE REACHED')+note(r.networkBlocked&&!r.appBlocked?'The application permits the route, but the independent egress policy stops the internal connection.':'Check each changed destination, then constrain the fetcher’s network authority.',r.internalReached);
},foot:'Three symbolic routes, not a URL parser or DNS model. Direct internal addresses always fail the initial allowlist. The egress policy blocks internal destinations while allowing the approved public host.'});

labs.tls=()=>({title:'Map the channel’s actual endpoints',state:{hostname:true,chain:true,expired:false,edgeOnly:true},controls:[T('hostname','Certificate matches expected hostname'),T('chain','Certificate chains to a trusted authority'),T('expired','Certificate is expired'),T('edgeOnly','Proxy sends plaintext to service')],render:s=>{
 const r=M.tlsModel(s);return gates([['Expected hostname',s.hostname],['Trusted chain',s.chain],['Within certificate lifetime',!s.expired]])+`<div class="sec-channel">${node('Client','Browser')}<span class="${r.clientToEdge?'pass':'fail'}">${r.clientToEdge?'TLS channel':'connection rejected'}</span>${node('Proxy','Terminates TLS','purple')}<span class="${r.edgeToService?'pass':'fail'}">${!r.authenticated?'no request':r.edgeToService?'separate TLS':'plaintext'}</span>${node('Service','Application','blue')}</div>`+note('A failed peer check stops the modeled client connection. A valid first channel says nothing about an unprotected next hop.');
},foot:'TLS server-identity abstraction. When enabled, the service hop is assumed independently authenticated. No actual certificates or cryptographic handshake are processed.'});

labs.aead=()=>({title:'Open a sealed record under the right context',state:{tamper:false,aadChanged:false,wrongKey:false,reuseNonce:false},controls:[T('tamper','Modify ciphertext'),T('aadChanged','Move record into another tenant context'),T('wrongKey','Use a different key'),T('reuseNonce','Nonce was reused under this key')],render:s=>{
 const r=M.aeadModel(s);return `<div class="sec-envelope"><small>SEALED RECORD</small><div><span>nonce</span><span>ciphertext ${s.tamper?'≠ original':''}</span><span>authentication tag</span></div><p>Associated data: tenant ${s.aadChanged?'B':'A'} · record type</p></div>`+tiles([['Authentication contract',r.verified?'Tag verifies':'Reject; release no plaintext',r.verified],['Nonce discipline',r.secureUse?'Unique in this scenario':'UNSAFE reuse',r.secureUse]])+note('Associated data is authenticated, not encrypted. Tag acceptance and safe nonce management are separate obligations.',!r.secureUse);
},foot:'AEAD contract model, not an encryption implementation. Assumes an original valid record and distinct modified fixtures; ignores negligible forgery probability. Nonce rule illustrates AES-GCM-style unique nonces.'});

labs.rotation=()=>({title:'Move the envelope before retiring its key',state:{rotated:false,rewrapped:false,oldKeyPresent:true,message:'The existing data key is wrapped by K1.'},controls:[B('rotate','Activate K2 for new writes'),B('rewrap','Rewrap existing data key'),B('retire','Destroy local K1')],actions:{rotate:s=>{s.rotated=true;s.message='New writes use K2. Existing wrappers are unchanged.';},rewrap:s=>{if(s.rotated&&s.oldKeyPresent){s.rewrapped=true;s.message='Current wrapper now uses K2; payload ciphertext is unchanged.';}else s.message='Cannot migrate: need both active K2 and K1 to open the old wrapper.';},retire:s=>{s.oldKeyPresent=false;s.message='K1 is unavailable locally. Any unmigrated data is now unreadable in this model.';}},render:s=>{
 const r=M.keyRotation(s);return `<div class="sec-envelope"><small>EXISTING RECORD</small>${flow([['Wrapping key',s.rewrapped?'K2':s.oldKeyPresent?'K1':'K1 missing','purple'],['Wrapped data key',s.rewrapped?'K2 envelope':'K1 envelope'],['Payload','Same encrypted bytes','blue']])}</div>`+stats(['New-write key',r.newWritesKey],['Existing record readable',r.oldReadable?'Yes':'No'],['Local K1',s.oldKeyPresent?'Present':'Destroyed'])+note(s.message,!r.oldReadable)+`<p class="small">A stolen K1 plus a copied old wrapper can still expose its data key, even after the current wrapper is migrated.</p>`;
},foot:'One envelope and one local key store. K2 remains available once activated. No replicas, backup key copies, or data-key compromise recovery; reset restores the original scenario.'});

labs.retention=()=>({title:'Follow a deletion across four copies',state:{deleteRequested:false,days:0},controls:[T('deleteRequested','Delete requested at day zero'),R('days','Days since request',0,35)],render:s=>{
 const copies=M.retainedCopies(s.days,s.deleteRequested);return `<div class="sec-copies">${copies.map((c,i)=>`<div class="${c.present?'present':'erased'}"><span>${c.present?'▤':'✓'}</span><strong>${c.name}</strong><small>${c.present?'still retained':'removed'} · deadline ${[0,1,7,30][i]}d</small></div>`).join('')}</div>`+stats(['Copies remaining',copies.filter(c=>c.present).length],['Deletion requested',s.deleteRequested?'Yes':'No'])+note('An old backup restore must reapply deletion records before serving restored data. Expiry is a policy with enforcement, not just a date in a document.');
},foot:'Illustrative fixed retention schedule; not a legal requirement. Timers start only with a deletion request. No additional replicas, holds, or undocumented exports are represented.'});

labs['supply-chain']=()=>({title:'Decide whether this build may ship',state:{digest:true,signature:true,builder:false,source:true},controls:[T('digest','Artifact digest matches provenance'),T('signature','Attestation authenticity verifies'),T('builder','Builder identity is approved'),T('source','Source revision is approved')],render:s=>{
 const checks=M.provenanceChecks(s);return flow([['Source','Approved revision'],['Builder','Isolated release process','purple'],['Artifact','Digest + provenance','blue']])+gates(checks)+verdict(checks.every(x=>x[1]),'Meets modeled release policy','Release rejected')+note('A signature from an unapproved builder still fails the policy. Passing provenance checks does not prove the source is free of vulnerabilities.');
},foot:'Consumer-policy model with fixed verification outcomes, not a signature verifier or a SLSA level assessment. Dependency risk and build isolation need separate evidence.'});

labs.secrets=()=>({title:'Migrate a client and close the exposed credential',state:{newIssued:false,clientNew:false,oldRevoked:false,message:'Both client and attacker have the old credential.'},controls:[B('issue','Issue replacement'),B('migrate','Move client to replacement'),B('revoke','Revoke exposed credential')],actions:{issue:s=>{s.newIssued=true;s.message='A replacement exists. The old credential has not changed.';},migrate:s=>{if(s.newIssued){s.clientNew=true;s.message='Client now uses the replacement.';}else s.message='Issue the replacement before moving the client.';},revoke:s=>{s.oldRevoked=true;s.message='The verifier rejects the old credential, including the attacker’s copy.';}},render:s=>{
 const r=M.secretState(s);return `<div class="sec-compare"><div><h3>Legitimate client</h3>${flow([['Credential',s.clientNew?'New':'Old'],['Request',r.legitimateWorks?'Accepted':'Rejected','blue']])}</div><div><h3>Copied credential</h3>${flow([['Credential','Old','purple'],['Request',r.stolenWorks?'Accepted':'Rejected','blue']])}</div></div>`+tiles([['Service continuity',r.legitimateWorks?'Available':'Client needs migration',r.legitimateWorks],['Exposed authority',r.stolenWorks?'Still usable':'Revoked',!r.stolenWorks]])+note(s.message,r.stolenWorks);
},foot:'One client and one verifier, immediate propagation. Active compromise can justify revocation before migration; real systems need to account for caches, dependent clients, and alternate credentials.'});

labs.hardening=()=>({title:'Inspect reach after process compromise',state:{root:true,readonly:false,hostSocket:true,egress:false},controls:[T('root','Process runs as container root'),T('readonly','Application filesystem is read-only'),T('hostSocket','Host control socket is mounted and accessible'),T('egress','Deny outbound internal-service access')],render:s=>{
 const reach=M.hardening(s);return `<div class="sec-capabilities"><div class="sec-principal">Compromised process<small>Same vulnerability in every configuration</small></div><div>${reach.map(r=>`<div class="sec-capability ${r.reachable?'reachable':''}"><span>${r.reachable?'→':'×'}</span>${r.name}<small>${r.reachable?'reachable':'restricted'}</small></div>`).join('')}</div></div>`+note('Remove the host socket independently of changing user. Read-only files do not prevent outbound network access. Each control narrows a different capability.');
},foot:'Specific assumed permissions in a toy container, not a kernel isolation model. Non-root still owns its application data and credentials; read-only application files exclude writable volumes.'});

labs.verification=()=>({title:'Reveal what a passing happy path misses',state:{object:false,tenant:false,defaultDeny:false,expiry:false},controls:[T('object','Implement object permission check'),T('tenant','Implement tenant permission check'),T('defaultDeny','Deny unknown actions'),T('expiry','Enforce credential expiry')],render:s=>{
 const results=M.assurance(s);return gates(results)+stats(['Positive tests passing','1 / 1'],['Negative cases passing',`${results.slice(1).filter(x=>x[1]).length} / 4`])+note('Each denied-case check assumes both a rejected response and no unauthorized side effect. Passing the first row never establishes the other four.');
},foot:'Expected outcomes from four independent control fixtures, not a real test runner. Real verification must exercise implementation and persistence, including paths through caches and jobs.'});

labs.abuse=()=>({title:'Budget the work behind each request',state:{requests:100,cost:10,limit:100,weighted:false},controls:[R('requests','Requests arriving in this window',10,200,10),R('cost','Work units per request',1,20),R('limit','Budget per window',20,200,10),T('weighted','Charge work units instead of request count')],render:s=>{
 const r=M.abuseBudget(s.requests,s.cost,s.limit,s.weighted);return bars([['Requested work',s.requests*s.cost,'#c4b5ed'],['Admitted work',r.work,'#edbd85'],['Available work capacity',s.limit,'#91cce2']])+stats(['Requests admitted',r.admitted],['Requests rejected',r.rejected],['Work / capacity',`${r.work} / ${s.limit}`])+note(r.work>s.limit?'The count limiter admits more work than the modeled capacity. Charging actual work prevents this specific overload.':'Admitted work fits this capacity budget. Other resources and concurrent requests need their own bounds.',r.work>s.limit);
},foot:'One fixed window, equal known request costs, admission charged before execution. No burst carryover, distributed counters, retries, or estimation error. Budget means requests in count mode and work units in cost mode.'});

labs.audit=()=>({title:'Keep the evidence; remove the credential',state:{includeSecret:false,structured:true},controls:[T('includeSecret','Accidentally include a bearer credential'),T('structured','Encode event as structured JSON')],render:s=>{
 const r=M.auditEvent(s.includeSecret,s.structured);return code(r.representation)+tiles([['Credential disclosure',s.includeSecret?'Secret copied into event':'Credential excluded',!s.includeSecret],['Untrusted newline',s.structured?'Encoded inside one value':'Can resemble a forged line',s.structured]])+note('The decision is deny. The user-controlled display label contains a newline followed by result=allow; it must remain data, not a second event.',s.includeSecret||!s.structured);
},foot:'Synthetic actor, resource, timestamp, and demonstration token. No credentials are read. JSON escapes the embedded newline; real log pipelines must preserve structured fields and restrict access.'});

labs.response=()=>({title:'Move from containment to verified recovery',state:{preserved:false,revoked:false,isolated:false,rebuilt:false,validated:false,message:'An exposed credential and a modified workload are both present.'},controls:[B('preserve','Preserve evidence'),B('revoke','Revoke exposed identity'),B('isolate','Isolate workload'),B('rebuild','Rebuild from trusted inputs'),B('validate','Validate recovery')],actions:{preserve:s=>{if(!s.rebuilt){s.preserved=true;s.message='Original evidence preserved for analysis.';}else s.message='Original workload was replaced; this model cannot recover the missing evidence.';},revoke:s=>{s.revoked=true;s.message='Exposed identity revoked. Installed persistence is a separate problem.';},isolate:s=>{s.isolated=true;s.message='This network route is isolated; the workload remains untrusted.';},rebuild:s=>{if(s.isolated){s.rebuilt=true;s.validated=false;s.message='Trusted replacement staged in isolation. Validate before reconnecting.';}else s.message='Isolate this workload before staging the replacement.';},validate:s=>{if(s.rebuilt&&s.revoked){s.validated=true;s.message='Integrity and access checks pass in this fixture. Ready for a controlled return.';}else s.message='Validation requires a trusted replacement and revoked exposed authority.';}},render:s=>{
 const r=M.responseState(s);return `<div class="sec-response">${[['Evidence',s.preserved],['Revoke',s.revoked],['Isolate',s.isolated],['Rebuild',s.rebuilt],['Validate',s.validated]].map(([label,done],i)=>`<div class="${done?'done':''}"><span>${String(i+1).padStart(2,'0')}</span><strong>${label}</strong><small>${done?'complete':'pending'}</small></div>`).join('')}</div>`+tiles([['Exposed entry route',r.activeAccess?'Open':'Contained',!r.activeAccess],['Installed foothold',r.persistence?'Still present':'Removed in replacement',!r.persistence],['Return to service',r.readyToReconnect?'Ready to reconnect':'Not ready',r.readyToReconnect]])+note(s.message)+(!s.preserved&&s.rebuilt?note('Recovery does not restore evidence destroyed by rebuilding. The investigation has an unresolved evidence gap.',true):'');
},foot:'One compromised workload and one exposed identity; button actions model distinct outcomes. Urgent containment may precede preservation. Validation is a successful fixture, not forensic proof; reconnection is not performed.'});

const incidents=[
 ['Private export returned to another tenant','Object authorization','Changing export_id returned another tenant’s rows. TLS and authentication were valid.'],
 ['Write happened although response was hidden','CSRF intent validation','A cross-site POST carried a session cookie. CORS blocked response access after the write.'],
 ['Fresh login code relayed from lookalike','Origin-bound authentication','The victim entered a valid OTP at the lookalike. The real service accepted the relayed proof.'],
 ['Replacement issued; stolen token still works','Revoke exposed credential','Client migration succeeded. The verifier still accepts the attacker’s old credential.']
];
labs.review=()=>({title:'Diagnose the guarantee that failed',state:{incident:incidents[0][0],control:'Object authorization'},controls:[C('incident','Observed incident',incidents.map(x=>x[0])),C('control','Control to validate',incidents.map(x=>x[1]))],render:s=>{
 const [title,correct,evidence]=incidents.find(x=>x[0]===s.incident),right=s.control===correct;return `<div class="sec-evidence"><small>OBSERVED EVIDENCE</small><h3>${title}</h3><p>${evidence}</p></div>`+flow([['Proposed fix',s.control,'purple'],['Boundary match',right?'Addresses the observed failure':'Does not repair this path','blue']])+note(right?'Next: add a regression that reproduces the unauthorized outcome, then proves both rejection and absence of side effects.':'Re-read what happened, then locate the missing guarantee. A useful mechanism at another boundary leaves this evidence unexplained.',!right);
},foot:'Four intentionally isolated incident fixtures. Real investigations can involve multiple failures and require evidence beyond the initial symptom.'});

export function mountLab(element,id){if(!labs[id])throw new Error(`Unknown security lab: ${id}`);return mountExperiment(element,labs[id]());}

export const labIds=()=>Object.keys(labs);
export const createLab=id=>labs[id]();
